CREATE VIRTUAL TABLE t4 USING fts3([norm],'plusone',"invert"); WITH RECURSIVE n(x) AS (VALUES(1) UNION ALL SELECT x+1 FROM n WHERE x<15) INSERT INTO t4(rowid,norm,plusone,invert) SELECT x, trim((CASE WHEN (x & 1)<>0 THEN 'one ' ELSE '' END)||(CASE WHEN (x & 2)<>0 THEN 'two ' ELSE '' END)||(CASE WHEN (x & 4)<>0 THEN 'three ' ELSE '' END)||(CASE WHEN (x & 8)<>0 THEN 'four ' ELSE '' END)||(CASE WHEN (x & 16)<>0 THEN 'five ' ELSE '' END)), trim((CASE WHEN ((x+1) & 1)<>0 THEN 'one ' ELSE '' END)||(CASE WHEN ((x+1) & 2)<>0 THEN 'two ' ELSE '' END)||(CASE WHEN ((x+1) & 4)<>0 THEN 'three ' ELSE '' END)||(CASE WHEN ((x+1) & 8)<>0 THEN 'four ' ELSE '' END)||(CASE WHEN ((x+1) & 16)<>0 THEN 'five ' ELSE '' END)), trim((CASE WHEN ((~x) & 1)<>0 THEN 'one ' ELSE '' END)||(CASE WHEN ((~x) & 2)<>0 THEN 'two ' ELSE '' END)||(CASE WHEN ((~x) & 4)<>0 THEN 'three ' ELSE '' END)||(CASE WHEN ((~x) & 8)<>0 THEN 'four ' ELSE '' END)||(CASE WHEN ((~x) & 16)<>0 THEN 'five ' ELSE '' END)) FROM n; CREATE TABLE result(rid INTEGER);